CREATE TABLE `body_paint_repair_orders` (
  `id` varchar(191) NOT NULL, `branch_id` varchar(191) NOT NULL, `customer_id` varchar(191) NOT NULL, `vehicle_id` varchar(191) NOT NULL,
  `order_no` varchar(50) NOT NULL, `complaint` varchar(1000) NULL, `status` enum('OPEN','ASSESSMENT','PENDING_APPROVAL','APPROVED','IN_PROGRESS','QUALITY_CHECK','READY_FOR_INVOICE','INVOICED','CLOSED','CANCELLED') NOT NULL DEFAULT 'OPEN',
  `opened_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `closed_at` datetime(3) NULL, `created_by_id` varchar(191) NULL,
  UNIQUE INDEX `body_paint_repair_orders_order_no_key` (`order_no`), INDEX `body_paint_repair_orders_branch_id_status_opened_at_idx` (`branch_id`,`status`,`opened_at`),
  PRIMARY KEY (`id`), CONSTRAINT `body_paint_repair_orders_branch_id_fkey` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`), CONSTRAINT `body_paint_repair_orders_customer_id_fkey` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`), CONSTRAINT `body_paint_repair_orders_vehicle_id_fkey` FOREIGN KEY (`vehicle_id`) REFERENCES `vehicles` (`id`), CONSTRAINT `body_paint_repair_orders_created_by_id_fkey` FOREIGN KEY (`created_by_id`) REFERENCES `users` (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `body_paint_insurance_cases` (`id` varchar(191) NOT NULL, `repair_order_id` varchar(191) NOT NULL, `insurer_name` varchar(160) NOT NULL, `policy_no` varchar(100) NULL, `claim_no` varchar(100) NULL, `status` enum('OPEN','SUBMITTED','APPROVED','REJECTED','SETTLED','CLOSED') NOT NULL DEFAULT 'OPEN', `approved_amount` decimal(18,4) NULL, `deductible` decimal(18,4) NOT NULL DEFAULT 0, `notes` varchar(1000) NULL, `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` datetime(3) NOT NULL, INDEX `body_paint_insurance_cases_repair_order_id_status_idx` (`repair_order_id`,`status`), PRIMARY KEY (`id`), CONSTRAINT `body_paint_insurance_cases_repair_order_id_fkey` FOREIGN KEY (`repair_order_id`) REFERENCES `body_paint_repair_orders` (`id`) ON DELETE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `body_paint_damage_assessments` (`id` varchar(191) NOT NULL, `repair_order_id` varchar(191) NOT NULL, `assessor_id` varchar(191) NULL, `damage_areas` json NOT NULL, `estimated_labor` decimal(18,4) NOT NULL DEFAULT 0, `estimated_materials` decimal(18,4) NOT NULL DEFAULT 0, `notes` varchar(1000) NULL, `assessed_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `body_paint_damage_assessments_repair_order_id_assessed_at_idx` (`repair_order_id`,`assessed_at`), PRIMARY KEY (`id`), CONSTRAINT `body_paint_damage_assessments_repair_order_id_fkey` FOREIGN KEY (`repair_order_id`) REFERENCES `body_paint_repair_orders` (`id`) ON DELETE CASCADE, CONSTRAINT `body_paint_damage_assessments_assessor_id_fkey` FOREIGN KEY (`assessor_id`) REFERENCES `users` (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `body_paint_approvals` (`id` varchar(191) NOT NULL, `repair_order_id` varchar(191) NOT NULL, `type` enum('CUSTOMER','INSURER') NOT NULL, `status` enum('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING', `approved_amount` decimal(18,4) NULL, `approved_by` varchar(160) NULL, `approved_at` datetime(3) NULL, `notes` varchar(1000) NULL, INDEX `body_paint_approvals_repair_order_id_type_status_idx` (`repair_order_id`,`type`,`status`), PRIMARY KEY (`id`), CONSTRAINT `body_paint_approvals_repair_order_id_fkey` FOREIGN KEY (`repair_order_id`) REFERENCES `body_paint_repair_orders` (`id`) ON DELETE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `body_paint_operations` (`id` varchar(191) NOT NULL, `repair_order_id` varchar(191) NOT NULL, `technician_id` varchar(191) NULL, `type` enum('BODY','PAINT') NOT NULL, `description` varchar(255) NOT NULL, `status` enum('PLANNED','IN_PROGRESS','COMPLETED','ON_HOLD') NOT NULL DEFAULT 'PLANNED', `hours` decimal(10,2) NOT NULL DEFAULT 0, `rate` decimal(18,4) NOT NULL DEFAULT 0, `started_at` datetime(3) NULL, `completed_at` datetime(3) NULL, INDEX `body_paint_operations_repair_order_id_status_idx` (`repair_order_id`,`status`), PRIMARY KEY (`id`), CONSTRAINT `body_paint_operations_repair_order_id_fkey` FOREIGN KEY (`repair_order_id`) REFERENCES `body_paint_repair_orders` (`id`) ON DELETE CASCADE, CONSTRAINT `body_paint_operations_technician_id_fkey` FOREIGN KEY (`technician_id`) REFERENCES `users` (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `body_paint_vehicle_movements` (`id` varchar(191) NOT NULL, `repair_order_id` varchar(191) NOT NULL, `from_location_id` varchar(191) NULL, `to_location_id` varchar(191) NULL, `moved_by_id` varchar(191) NULL, `moved_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `notes` varchar(500) NULL, INDEX `body_paint_vehicle_movements_repair_order_id_moved_at_idx` (`repair_order_id`,`moved_at`), PRIMARY KEY (`id`), CONSTRAINT `body_paint_vehicle_movements_repair_order_id_fkey` FOREIGN KEY (`repair_order_id`) REFERENCES `body_paint_repair_orders` (`id`) ON DELETE CASCADE, CONSTRAINT `body_paint_vehicle_movements_from_location_id_fkey` FOREIGN KEY (`from_location_id`) REFERENCES `locations` (`id`), CONSTRAINT `body_paint_vehicle_movements_to_location_id_fkey` FOREIGN KEY (`to_location_id`) REFERENCES `locations` (`id`), CONSTRAINT `body_paint_vehicle_movements_moved_by_id_fkey` FOREIGN KEY (`moved_by_id`) REFERENCES `users` (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `body_paint_material_consumptions` (`id` varchar(191) NOT NULL, `repair_order_id` varchar(191) NOT NULL, `part_id` varchar(191) NOT NULL, `operation_id` varchar(191) NULL, `quantity` decimal(18,4) NOT NULL, `unit_cost` decimal(18,4) NOT NULL DEFAULT 0, `consumed_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `body_paint_material_consumptions_repair_order_id_consumed_at_idx` (`repair_order_id`,`consumed_at`), PRIMARY KEY (`id`), CONSTRAINT `body_paint_material_consumptions_repair_order_id_fkey` FOREIGN KEY (`repair_order_id`) REFERENCES `body_paint_repair_orders` (`id`) ON DELETE CASCADE, CONSTRAINT `body_paint_material_consumptions_part_id_fkey` FOREIGN KEY (`part_id`) REFERENCES `parts` (`id`), CONSTRAINT `body_paint_material_consumptions_operation_id_fkey` FOREIGN KEY (`operation_id`) REFERENCES `body_paint_operations` (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `body_paint_invoice_ready_summaries` (`id` varchar(191) NOT NULL, `repair_order_id` varchar(191) NOT NULL, `labor_total` decimal(18,4) NOT NULL DEFAULT 0, `materials_total` decimal(18,4) NOT NULL DEFAULT 0, `other_total` decimal(18,4) NOT NULL DEFAULT 0, `subtotal` decimal(18,4) NOT NULL, `tax` decimal(18,4) NOT NULL DEFAULT 0, `total` decimal(18,4) NOT NULL, `generated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `body_paint_invoice_ready_summaries_repair_order_id_key` (`repair_order_id`), PRIMARY KEY (`id`), CONSTRAINT `body_paint_invoice_ready_summaries_repair_order_id_fkey` FOREIGN KEY (`repair_order_id`) REFERENCES `body_paint_repair_orders` (`id`) ON DELETE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
